mutation fulfillmentCreateV2($fulfillment: FulfillmentV2Input!, $message: String) {
  fulfillmentCreateV2(fulfillment: $fulfillment, message: $message) {
    fulfillment {
      id
      status
      createdAt
      trackingInfo {
        company
        number
        url
      }
      fulfillmentLineItems(first: 50) {
        nodes {
          quantity
          lineItem {
            id
            sku
            name
          }
        }
      }
      order {
        id
        name
      }
    }
    userErrors {
      field
      message
    }
  }
}

=query getOrderForAngloImport($query: String!) {
  orders(first: 5, query: $query) {
    nodes {
      id
      number
      displayFulfillmentStatus
      lineItems(first: 25) {
        nodes {
          id
          sku
          variant {
            metafield(key: "parent_variant", namespace: "custom") {
              reference {
                ... on ProductVariant {
                  id
                  sku
                }
              }
            }
          }
          quantity
        }
      }
      fulfillments(first: 7) {
        status
        fulfillmentLineItems(first: 20) {
          nodes {
            lineItem {
              id
              sku
              variant {
                metafield(key: "parent_variant", namespace: "custom") {
                  reference {
                    ... on ProductVariant {
                      id
                      sku
                    }
                  }
                }
              }
            }
            id
          }
        }
      }
      fulfillmentOrders(first: 5) {
        nodes {
          id
          status
          lineItems(first: 20) {
            nodes {
              id
              sku
              variant {
                metafield(key: "parent_variant", namespace: "custom") {
                  reference {
                    ... on ProductVariant {
                      id
                      sku
                    }
                  }
                }
              }
              lineItem {
                fulfillmentStatus
              }
            }
          }
        }
      }
    }
  }
}

