// Step 1: Get all incoming items
const rows = items.map(item => item.json);



// Step 2: Group by shipment (order + consignment)
const shipmentGroups = {};

for (const row of rows) {
  const shipmentKey = `${row.base_order_ref}|${row.shipment_part}|${row["Consignment No"]}`;

  if (!shipmentGroups[shipmentKey]) {

    const trackingInfo = {
      company: row["Delivery Method"]
    };

    // Only add number if it exists
    if (row["Consignment No"]) {
      trackingInfo.number = row["Consignment No"];
    }

    // Only add url if it exists
    if (row["courier_url"]) {
      trackingInfo.url = row["courier_url"];
    }

    shipmentGroups[shipmentKey] = {
      trackingInfo,
      fulfillmentOrders: {}
    };
  }

  const group = shipmentGroups[shipmentKey];

  // Step 3: Group inside shipment by fulfillmentOrderId
  if (!group.fulfillmentOrders[row.fulfillmentOrderId]) {
    group.fulfillmentOrders[row.fulfillmentOrderId] = [];
  }

  // Step 4: Push line item into correct fulfillment order
  group.fulfillmentOrders[row.fulfillmentOrderId].push({
    id: row.fulfillmentOrderSkuId, // replace with fulfillmentOrderLineItemId when available
    quantity: row.quantity
  });
}

// Step 5: Convert grouped object into Shopify structure
const output = [];

for (const shipmentKey in shipmentGroups) {
  const shipment = shipmentGroups[shipmentKey];

  const lineItemsByFulfillmentOrder = [];

  for (const fulfillmentOrderId in shipment.fulfillmentOrders) {
    lineItemsByFulfillmentOrder.push({
      fulfillmentOrderId,
      fulfillmentOrderLineItems: shipment.fulfillmentOrders[fulfillmentOrderId]
    });
  }

  output.push({
    json: {
      fulfillment: {
        trackingInfo: shipment.trackingInfo,
        notifyCustomer: false,
        lineItemsByFulfillmentOrder
      }
    }
  });
}

return output;

